{
  "description": "The creature is shown in right-facing profile on a plain light background. It has the overall body, head, fur, hind legs and bushy tail of a gray wolf, with dense gray, white and beige fur and a thick ruff around the neck, but its back from the shoulders to the hips is covered by a large, dark bluish-gray, glossy segmented shell with frilled and spiked edges, and its two forelimbs are thick, heavily armored, jointed limbs ending in large crab-like pincers that rest on the ground alongside the hind paws. The head is wolf-like with a pointed muzzle, black nose and yellow eyes, and the hindquarters and tail remain fully wolf-like.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like head with a long narrow muzzle, black nose, yellow eyes, white fur around the muzzle and cheeks and gray fur on top",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with dark interiors and gray outer fur",
      "where": "on top of the head"
    },
    {
      "part": "mane",
      "looks_like": "thick shaggy ruff of long gray and off-white fur",
      "where": "encircling the neck and extending down the chest and along the underside of the body"
    },
    {
      "part": "legs",
      "looks_like": "four legs: two hind legs with natural wolf musculature and fur, and two front legs that are thick, jointed and completely encased in dark glossy segmented armor",
      "where": "hind legs at the rear under the hips, front armored legs under the shoulders in the middle-front"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with toes, pads and small claws; front feet are large dark crab-like pincers with a fixed and movable finger and black tips",
      "where": "at the bottom ends of the legs, all four touching the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy, fur-covered tail with mixed gray, beige and dark hairs, hanging down",
      "where": "at the extreme rear of the body behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large dome-shaped dark bluish-gray segmented carapace with transverse ridged segments, a broad frilled and spiked front plate and smaller pointed rear segments, glossy with speckled texture",
      "where": "sitting on the dorsal midline covering the back from just behind the shoulders to above the hindquarters, overlapping the fur"
    },
    {
      "part": "plates",
      "looks_like": "hard, glossy, overlapping jointed plates with visible seams and ridges forming continuous armor",
      "where": "covering the entire length of both front legs from the shoulder joint down to the base of the pincers"
    },
    {
      "part": "markings",
      "looks_like": "dense wolf fur with mottled gray on the back and sides, lighter beige and white on the belly, chest, inner legs and around the muzzle, with natural shading",
      "where": "covering all exposed skin except the shell and front-leg armor"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
